mapper.select:
SELECT p.id, p.main_image mainImage, p.images images, p.product_name productName, p.spec_model specModel, p.product_code productCode, p.category_id categoryId, p.category_name categoryName, p.brand_id brandId, p.brand_name brandName, p.supplier_name supplierName, p.manufacturer manufacturer, p.unit unit, p.cost_price costPrice, p.sale_price salePrice, p.showcase_position showcasePosition, p.shelf_status shelfStatus, p.sort sort, p.create_time createTime, p.update_time updateTime, p.is_deleted isDeleted, coalesce(s.stock, 0) stock, coalesce(s.stock_warn, 0) stockWarn FROM goods_product p LEFT JOIN inventory_stock s ON p.id = s.goods_id
p.is_deleted = 0
AND (p.product_name LIKE CONCAT('%',#{keyword},'%') OR p.product_code LIKE CONCAT('%',#{keyword},'%'))
AND p.category_id = #{categoryId}
AND p.brand_id = #{brandId}
AND p.shelf_status = #{shelfStatus}
AND p.product_code = #{productCode}
AND p.sale_price >= #{minPrice}
AND p.sale_price <= #{maxPrice}
ORDER BY p.sort ASC,p.create_time DESC
